from collections import Counter
class Solution:
 def relativeSortArray(self,arr1,arr2):
  c=Counter(arr1);out=[]
  for x in arr2:out.extend([x]*c.pop(x,0))
  for x in sorted(c):out.extend([x]*c[x])
  return out

class Solution:
 def numEquivDominoPairs(self,dominoes):
  count={};ans=0
  for a,b in dominoes:
   key=(min(a,b),max(a,b));ans+=count.get(key,0);count[key]=count.get(key,0)+1
  return ans

class Solution:
 def tribonacci(self,n):
  a,b,c=0,1,1
  for _ in range(n):a,b,c=b,c,a+b+c
  return a

