from collections import Counter
class Solution:
 def countCharacters(self,words,chars):
  have=Counter(chars);total=0
  for w in words:
   need=Counter(w)
   if all(need[c]<=have[c] for c in need):total+=len(w)
  return total

from bisect import bisect_right
class Solution:
 def numSmallerByFrequency(self,queries,words):
  def f(s):
   c=min(s);return s.count(c)
  a=sorted(f(w) for w in words)
  return [len(a)-bisect_right(a,f(q)) for q in queries]

class Solution:
 def distanceBetweenBusStops(self,distance,start,destination):
  if start>destination:start,destination=destination,start
  clockwise=sum(distance[start:destination]);return min(clockwise,sum(distance)-clockwise)

